import{_ as e,o as r,c as s,a5 as a}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse('{"title":"Modèle économique Vendora — formule gratuite, formules payantes, IA et API","description":"","frontmatter":{},"headers":[],"relativePath":"commercial/modele-economique.md","filePath":"generated/commercial/modele-economique.md","lastUpdated":null}'),d={name:"commercial/modele-economique.md"};function i(o,t,n,l,u,c){return r(),s("div",null,[...t[0]||(t[0]=[a('<div><h1 id="modele-economique-vendora-—-formule-gratuite-formules-payantes-ia-et-api" tabindex="-1">Modèle économique Vendora — formule gratuite, formules payantes, IA et API <a class="header-anchor" href="#modele-economique-vendora-—-formule-gratuite-formules-payantes-ia-et-api" aria-label="Permalink to &quot;Modèle économique Vendora — formule gratuite, formules payantes, IA et API&quot;">​</a></h1><blockquote><p><strong>Date</strong> : 11/11/2026 · <strong>Statut</strong> : <strong>orientations validées par Ahmed le 11/11/2026</strong> (§ 10), prix et quotas encore ajustables ; rien n&#39;est encore appliqué dans le produit · <strong>Auteur</strong> : équipe Vendora</p><p>Références : <a href="/VendoraSystem-docs/commercial/etude-concurrentielle">étude concurrentielle</a> · <a href="/VendoraSystem-docs/commercial/etude-commerciale">étude commerciale et positionnement</a> · <a href="/VendoraSystem-docs/commercial/plan-commercialisation">plan de commercialisation par Internet</a> · <a href="/VendoraSystem-docs/commercial/etude-gaas">étude GaaS</a> · <a href="/VendoraSystem-docs/architecture/mcp-vendora">serveur MCP Vendora</a> · <a href="/VendoraSystem-docs/architecture/api-publique">API publique</a> · <a href="/VendoraSystem-docs/specs/17-platform-console">Console Vendora (spec 17)</a>.</p><p>Les prix sont <strong>hors taxes</strong>. Les repères concurrents viennent des études du 25/10 et du 05/11/2026 ; à rafraîchir avant toute décision.</p></blockquote><hr><h2 id="_1-en-resume" tabindex="-1">1. En résumé <a class="header-anchor" href="#_1-en-resume" aria-label="Permalink to &quot;1. En résumé&quot;">​</a></h2><ol><li><strong>Point de départ</strong> (idée d&#39;Ahmed) : logiciel gratuit, seule la partie IA (MCP) payante après 3 mois d&#39;essai ; API gratuite 3 mois puis payante.</li><li><strong>Ce qui est gardé</strong> : le gratuit comme moteur d&#39;acquisition, et l&#39;IA comme différenciant. Aucun concurrent du panel ne propose d&#39;assistant IA branché sur la caisse, et aucun acteur tunisien n&#39;en a.</li><li><strong>Ce qui est corrigé</strong> : <ul><li>le gratuit est <strong>limité</strong> (1 magasin, 1 appareil) au lieu d&#39;être total ;</li><li>ce qui coûte cher reste payant : conformité certifiée, e-reporting, support, plusieurs appareils ;</li><li>l&#39;IA devient un <strong>accélérateur</strong> de revenus, pas la seule source.</li></ul></li><li><strong>Pourquoi</strong> : <ul><li>les « gratuits » français (SumUp, Square, Zettle) vivent de la commission sur les paiements (1,65 à 1,75 %), et Vendora n&#39;en prend pas ;</li><li>l&#39;e-reporting France coûte <strong>9 à 25 € par mois et par client</strong> chez la plateforme agréée ;</li><li>le freemium convertit en moyenne 2 à 5 % des inscrits ;</li><li>le petit commerçant paie pour « ma caisse tombe juste », « je suis en règle », « j&#39;ai 3 caisses », pas d&#39;abord pour une IA.</li></ul></li><li><strong>Règle de découpe</strong> : ce qui fait <strong>vendre</strong> une caisse est gratuit ; ce qui fait <strong>gagner ou économiser</strong> de l&#39;argent est payant ; ce qui <strong>coûte</strong> à Vendora (conformité, IA, matériel, support) n&#39;est jamais gratuit.</li></ol><h2 id="_2-les-formules" tabindex="-1">2. Les formules <a class="header-anchor" href="#_2-les-formules" aria-label="Permalink to &quot;2. Les formules&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>🆓 <strong>Gratuit</strong></th><th>🛒 <strong>Commerce</strong></th><th>🍽️ <strong>Restaurant</strong></th><th>🏢 <strong>Sur mesure</strong></th></tr></thead><tbody><tr><td><strong>Tunisie, mensuel</strong></td><td>0 DT</td><td><strong>39 DT</strong></td><td><strong>69 DT</strong></td><td>Devis (≈ 59 DT par magasin)</td></tr><tr><td><strong>Tunisie, annuel</strong> (10 mois payés)</td><td>—</td><td>390 DT</td><td>690 DT</td><td>Devis</td></tr><tr><td><strong>France, mensuel</strong></td><td>0 €</td><td><strong>29 €</strong></td><td><strong>59 €</strong></td><td>Devis (≈ 49 € par magasin)</td></tr><tr><td><strong>France, annuel</strong> (10 mois payés)</td><td>—</td><td>290 €</td><td>590 €</td><td>Devis</td></tr><tr><td><strong>Magasins</strong></td><td>1</td><td>1</td><td>1</td><td>Plusieurs</td></tr><tr><td><strong>Appareils inclus</strong></td><td>1 + back-office web</td><td>3</td><td>6</td><td>À la carte</td></tr><tr><td><strong>Produits</strong></td><td>300</td><td>Illimité</td><td>Illimité</td><td>Illimité</td></tr><tr><td><strong>Utilisateurs</strong></td><td>3 (1 propriétaire + 2 caissiers)</td><td>Illimité</td><td>Illimité</td><td>Illimité</td></tr><tr><td><strong>Engagement / commission</strong></td><td>Aucun</td><td>Aucun</td><td>Aucun</td><td>Aucun</td></tr><tr><td><strong>Repère concurrent</strong></td><td>Hiboutik, SumUp (0 € + commission)</td><td>Kesti 29 DT · Tactill 39 €</td><td>Al-Makhzan 79 DT · Square 59 € · Lightspeed 89 €</td><td>Zelty, Innovorder sur devis</td></tr></tbody></table><p>Pour comparaison, la grille précédente (<a href="/VendoraSystem-docs/commercial/etude-commerciale">étude commerciale</a>, <a href="/VendoraSystem-docs/commercial/plan-commercialisation">plan de commercialisation</a>) était sans formule gratuite :</p><ul><li>Tunisie : Essentiel 39 DT, Commerce 69 DT, Restaurant 99 DT ;</li><li>France : 29 / 49 / 79 €.</li></ul><p>La nouvelle grille baisse chaque palier d&#39;un cran, la formule Gratuit prenant la place de l&#39;Essentiel.</p><h2 id="_3-les-fonctionnalites-par-formule" tabindex="-1">3. Les fonctionnalités par formule <a class="header-anchor" href="#_3-les-fonctionnalites-par-formule" aria-label="Permalink to &quot;3. Les fonctionnalités par formule&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>🆓 Gratuit</th><th>🛒 Commerce</th><th>🍽️ Restaurant</th><th>🏢 Sur mesure</th></tr></thead><tbody><tr><td>Vente, encaissement, retours, ticket, reçu QR</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Mode hors ligne complet</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Sessions de caisse, rapports X et Z chaînés</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Catalogue, codes-barres, poids, CSV</td><td>✅ (300 produits)</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Stock de base et alertes de seuil bas</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Stock avancé (inventaire par scan, lots, dates limites, coût moyen)</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Fiche et historique client</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Fidélité (points, paliers)</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>Ardoise / karna</strong> de base (vente à crédit avec plafond, règlements, solde)</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Ardoise avancée (rappels automatiques, rapport des ardoises ouvertes, points différés)</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Fournisseurs et achats, suggestion de commande</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Anti-fraude (écarts, alertes, audit)</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Rapports</td><td>Ventes du jour + Z</td><td>Complets + email quotidien</td><td>+ food-cost, pourboires</td><td>+ consolidés</td></tr><tr><td>Export compta (FEC, journaux)</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Salle, KDS, téléphone serveur, partage d&#39;addition</td><td>—</td><td>—</td><td>✅</td><td>✅</td></tr><tr><td>Fiches techniques et marge par plat</td><td>—</td><td>—</td><td>✅</td><td>✅</td></tr><tr><td>Multi-magasins (catalogue commun, transferts)</td><td>—</td><td>—</td><td>—</td><td>✅</td></tr><tr><td>Marque blanche</td><td>—</td><td>—</td><td>—</td><td>✅</td></tr><tr><td>Thème, logo, FR / EN / AR</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Conformité de base (Z chaîné, archive 6 ans)</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>Conformité Tunisie (NACEF)</strong>, une fois homologuée</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>E-reporting France 2027</strong></td><td>—</td><td>Option</td><td>✅</td><td>✅</td></tr><tr><td>Mention « Propulsé par Vendora » sur le ticket</td><td>Oui</td><td>Non</td><td>Non</td><td>Non</td></tr><tr><td>Support</td><td>Centre d&#39;aide</td><td>Email + WhatsApp</td><td>Email + WhatsApp prioritaire</td><td>Interlocuteur dédié</td></tr><tr><td><strong>Quota API gratuit / mois</strong></td><td>1 000 appels</td><td>5 000</td><td>10 000</td><td>50 000</td></tr><tr><td><strong>Assistant IA</strong></td><td>—</td><td>3 mois offerts</td><td>3 mois offerts</td><td>✅ inclus</td></tr></tbody></table><p>Pourquoi cette découpe :</p><ul><li><strong>Le gratuit est vraiment utilisable</strong> : un petit commerçant encaisse, sort son Z et suit ses ventes à vie. Chaque ticket imprimé fait de la publicité à Vendora.</li><li><strong>L&#39;ardoise de base est gratuite</strong> (décision du 11/11) : c&#39;est l&#39;aimant du marché tunisien. Les rappels automatiques et le suivi des ardoises ouvertes restent payants.</li><li><strong>L&#39;anti-fraude, la fidélité et le stock avancé sont les déclencheurs d&#39;achat</strong> d&#39;une supérette. Ils sont payants dès 39 DT, sous Al-Makhzan (79 DT).</li><li><strong>La conformité certifiée n&#39;est jamais gratuite</strong>, parce qu&#39;elle coûte chaque mois à Vendora.</li></ul><h2 id="_4-les-options" tabindex="-1">4. Les options <a class="header-anchor" href="#_4-les-options" aria-label="Permalink to &quot;4. Les options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>🇹🇳 Tunisie</th><th>🇫🇷 France</th><th>Remarque</th></tr></thead><tbody><tr><td>Appareil supplémentaire</td><td>10 DT/mois</td><td>7 €/mois</td><td>Disponible même en Gratuit, comme marche douce vers Commerce</td></tr><tr><td>Kiosque en libre-service</td><td>29 DT/mois par borne</td><td>19 €/mois par borne</td><td></td></tr><tr><td>Menu QR / click &amp; collect (à venir, spec 16)</td><td>19 DT/mois</td><td>15 €/mois</td><td></td></tr><tr><td>E-reporting France (formule Commerce)</td><td>—</td><td>5 €/mois</td><td>En attente de la négociation avec la plateforme agréée</td></tr><tr><td>Support prioritaire soir et week-end</td><td>20 DT/mois</td><td>9 €/mois</td><td>Quand une astreinte existera</td></tr></tbody></table><h2 id="_5-l-ia-mcp-et-agents-gaas" tabindex="-1">5. L&#39;IA (MCP et agents GaaS) <a class="header-anchor" href="#_5-l-ia-mcp-et-agents-gaas" aria-label="Permalink to &quot;5. L&#39;IA (MCP et agents GaaS)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Offre</th><th>🇹🇳 Tunisie</th><th>🇫🇷 France</th><th>Remarque</th></tr></thead><tbody><tr><td><strong>Assistant IA (MCP, lecture seule)</strong></td><td><strong>3 mois offerts</strong>, puis 15 DT/mois</td><td><strong>3 mois offerts</strong>, puis 7 €/mois</td><td>Formules payantes seulement ; inclus en Sur mesure</td></tr><tr><td>Pack Agents Gestion (réassort, anti-fraude, clôtures)</td><td>29 DT/mois</td><td>15 €/mois</td><td>Pilote T1 2027</td></tr><tr><td>Agent clients (relances d&#39;ardoise, fidélité)</td><td>19 DT/mois + messages</td><td>12 €/mois + messages</td><td></td></tr><tr><td>Pilote automatique (tous les agents)</td><td>59 DT/mois</td><td>29 €/mois</td><td></td></tr></tbody></table><ul><li><strong>Règle d&#39;or</strong> (reprise de l&#39;étude GaaS) : l&#39;agent propose et l&#39;humain valide ; le fiscal n&#39;est jamais automatisé.</li><li><strong>Cible réelle</strong> : franchises et multi-sites d&#39;abord (« compare mes 3 magasins cette semaine »). Pour l&#39;épicier seul, l&#39;IA restera un bonus pendant un à deux ans.</li><li><strong>Prix revus</strong> : ils sont plus bas que ceux de l&#39;étude GaaS (19 € / 39 DT pour le Pack Gestion), par cohérence avec la baisse des formules. Le coût des modèles reste faible, 0,5 à 3 € par mois et par commerce selon l&#39;étude.</li></ul><h2 id="_6-l-api-publique-quota-gratuit-puis-paiement-a-l-usage" tabindex="-1">6. L&#39;API publique : quota gratuit puis paiement à l&#39;usage <a class="header-anchor" href="#_6-l-api-publique-quota-gratuit-puis-paiement-a-l-usage" aria-label="Permalink to &quot;6. L&#39;API publique : quota gratuit puis paiement à l&#39;usage&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>🇹🇳 Tunisie</th><th>🇫🇷 France</th></tr></thead><tbody><tr><td>Quota gratuit mensuel</td><td>Selon la formule (1 000 → 50 000 appels)</td><td>Pareil</td></tr><tr><td>Au-delà du quota</td><td><strong>Packs prépayés</strong> : 10 000 appels = 15 DT</td><td><strong>Paiement à l&#39;usage</strong> : 1 € pour 1 000 appels</td></tr><tr><td>Plafond de dépense</td><td>Le pack lui-même</td><td>50 €/mois par défaut, modifiable par le client, alerte à 80 %</td></tr><tr><td>Non décompté</td><td>Webhooks, appels de l&#39;assistant IA</td><td>Pareil</td></tr><tr><td>Partenaires (comptables, intégrateurs)</td><td>Quota élargi + commission sur les clients amenés</td><td>Pareil</td></tr></tbody></table><p>Les trois garde-fous et leur raison :</p><ol><li><strong>Plafond de dépense</strong> : une boucle mal codée chez un intégrateur ne doit jamais produire une facture surprise.</li><li><strong>Packs prépayés en Tunisie</strong> : la carte bancaire y est peu répandue, il y a le contrôle des changes, et la facturation de la console est manuelle aujourd&#39;hui.</li><li><strong>Appels de l&#39;assistant IA hors quota</strong> : ils sont déjà inclus dans l&#39;option IA, avec un usage raisonnable. Sinon le commerçant paierait deux fois.</li></ol><p>Le quota est <strong>permanent</strong> et non limité à 3 mois. Les comptables et les intégrateurs qui construisent sur l&#39;API amènent des clients.</p><h2 id="_7-services" tabindex="-1">7. Services <a class="header-anchor" href="#_7-services" aria-label="Permalink to &quot;7. Services&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>🇹🇳 Tunisie</th><th>🇫🇷 France</th></tr></thead><tbody><tr><td>Mise en service à distance (import, appairage, 1 h)</td><td>Gratuite</td><td>Gratuite</td></tr><tr><td>Installation et formation sur place</td><td>120 DT (offerte en annuel)</td><td>150 € (via revendeur)</td></tr><tr><td>Matériel</td><td>Packs via revendeur partenaire, avec commission</td><td>Pareil</td></tr><tr><td>Paiement par carte</td><td><strong>Hors du modèle pour l&#39;instant</strong> (décision du 11/11) : aucun partenaire contacté. À rouvrir plus tard (Konnect, Flouci, TUNPAY avec reversement)</td><td>Pareil</td></tr></tbody></table><h2 id="_8-offres-de-lancement" tabindex="-1">8. Offres de lancement <a class="header-anchor" href="#_8-offres-de-lancement" aria-label="Permalink to &quot;8. Offres de lancement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Offre</th><th>Pour qui</th><th>Contenu</th></tr></thead><tbody><tr><td><strong>Programme pilote</strong></td><td>10 commerces (6 TN, 4 FR)</td><td>Restaurant gratuit 3 mois, contre un témoignage et des captures</td></tr><tr><td><strong>Offre fondateurs</strong></td><td>30 premiers clients payants</td><td>−30 % pendant 12 mois</td></tr><tr><td><strong>Rachat d&#39;engagement</strong> (France)</td><td>Client encore engagé ailleurs</td><td>Gratuit jusqu&#39;à la fin de son contrat, 3 mois maximum</td></tr></tbody></table><p><strong>Lien avec l&#39;essai de 2 mois déjà en place</strong> (<code>PlatformConfig.trialDays</code> = 60) : l&#39;essai devient un <strong>essai des formules payantes</strong>. À la fin de l&#39;essai, sans paiement, le commerce <strong>redescend en Gratuit</strong> au lieu d&#39;être suspendu. Il garde ses ventes et ses Z, et perd les fonctions payantes.</p><h2 id="_9-points-de-vigilance" tabindex="-1">9. Points de vigilance <a class="header-anchor" href="#_9-points-de-vigilance" aria-label="Permalink to &quot;9. Points de vigilance&quot;">​</a></h2><ul><li><strong>Revenu</strong> : la baisse coûte environ −25 à −30 % de revenu à nombre de clients égal. L&#39;objectif à 12 mois de l&#39;étude commerciale (≈ 3 700 €/mois) demande environ <strong>150 clients payants</strong> au lieu de 110. Le gratuit doit compenser en volume. <strong>[Estimation]</strong></li><li><strong>E-reporting</strong> : négocier le prix en volume avec la plateforme agréée avant de l&#39;inclure partout, sinon Commerce France perd de l&#39;argent.</li><li><strong>Produit à construire avant d&#39;appliquer</strong> : <ul><li>formule Gratuit et descente en Gratuit à la fin de l&#39;essai (console, limites serveur) ;</li><li>limites de produits et d&#39;utilisateurs ;</li><li>mention « Propulsé par Vendora » sur le ticket ;</li><li>compteur d&#39;appels API par clé, plafond de dépense, packs prépayés ;</li><li>option IA avec ses 3 mois offerts.</li></ul></li><li><strong>Conformité</strong> : NACEF et NF525 sont toujours bloqués. On ne vend pas la « conformité incluse » avant de l&#39;avoir obtenue.</li><li><strong>Catalogue de la console et page Tarifs</strong> : ils affichent encore l&#39;ancienne grille. À mettre à jour seulement quand ce modèle sera validé.</li></ul><h2 id="_10-decisions-d-ahmed-11-11-2026" tabindex="-1">10. Décisions d&#39;Ahmed (11/11/2026) <a class="header-anchor" href="#_10-decisions-d-ahmed-11-11-2026" aria-label="Permalink to &quot;10. Décisions d&#39;Ahmed (11/11/2026)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Question</th><th>Décision</th><th>Conséquence dans ce modèle</th></tr></thead><tbody><tr><td>1</td><td>Objectif à 12 mois</td><td><strong>Beaucoup de clients d&#39;abord</strong>, levée de fonds ou rachat envisagés après 12 mois, et <strong>rentabilité rapide en parallèle</strong></td><td>Le gratuit reste <strong>limité</strong> (1 magasin, 1 appareil) : il attire du volume sans porter les coûts. Les formules payantes doivent couvrir les coûts dès le premier client</td></tr><tr><td>2</td><td>Un ou deux modèles</td><td><strong>Même découpage en France et en Tunisie</strong>, sinon les clients choisiront l&#39;offre la moins chère</td><td>Les fonctionnalités par formule sont identiques dans les deux pays. Seuls les <strong>prix</strong> changent, et ils sont fixés par le <strong>pays du commerce</strong> (adresse, devise et module fiscal NACEF ou NF525), pas au choix du client</td></tr><tr><td>3</td><td>Paiements</td><td><strong>Rester en dehors pour l&#39;instant</strong> : pas de plan, aucun partenaire contacté</td><td>Pas de commission ni de reversement ; la ligne « paiement par carte » des services est mise de côté</td></tr><tr><td>4</td><td>L&#39;ardoise</td><td><strong>L&#39;offrir dans le gratuit</strong></td><td>Pour respecter le même découpage (décision 2), l&#39;ardoise <strong>de base</strong> est gratuite <strong>dans les deux pays</strong>. Elle compte peu en France et pèse beaucoup en Tunisie. Les rappels automatiques et le rapport des ardoises ouvertes restent dans Commerce pour garder un levier de conversion</td></tr></tbody></table><p>Prochaine étape : appliquer le modèle dans le produit, selon le plan du § 11.</p><h2 id="_11-plan-d-application-dans-le-produit-planifie-le-11-11-2026-pas-commence" tabindex="-1">11. Plan d&#39;application dans le produit (planifié le 11/11/2026, pas commencé) <a class="header-anchor" href="#_11-plan-d-application-dans-le-produit-planifie-le-11-11-2026-pas-commence" aria-label="Permalink to &quot;11. Plan d&#39;application dans le produit (planifié le 11/11/2026, pas commencé)&quot;">​</a></h2><h3 id="ce-qui-existe-deja-et-sera-reutilise" tabindex="-1">Ce qui existe déjà et sera réutilisé <a class="header-anchor" href="#ce-qui-existe-deja-et-sera-reutilise" aria-label="Permalink to &quot;Ce qui existe déjà et sera réutilisé&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Brique</th><th>Où</th><th>Ce qu&#39;elle fait aujourd&#39;hui</th></tr></thead><tbody><tr><td>Catalogue des formules versionné</td><td>Console, table <code>platform_plans</code> (RG-PLAT-13)</td><td>Prix mensuel <strong>en euros seulement</strong>, <code>maxStores</code>, <code>maxDevices</code>, modules inclus, prix de l&#39;appareil supplémentaire. Le prix est figé à la souscription</td></tr><tr><td>Droits appliqués par le serveur</td><td><code>PlatformEntitlements</code> (RG-PLAT-14 à 16)</td><td>Refus <code>409 LIMIT_REACHED</code>. Les droits sont diffusés aux appareils (<code>TenantEntitlementsUpdated</code>) pour masquer les modules. Une baisse de formule n&#39;est jamais rétroactive</td></tr><tr><td>Modules activables</td><td><code>VendoraModules</code> (shared)</td><td><code>LOYALTY</code>, <code>CREDIT</code>, <code>SUPPLIERS</code>, <code>INVENTORY_COUNTS</code>, <code>FRAUD</code>, <code>TABLES</code>, <code>KITCHEN</code>, <code>TIPS</code>, <code>WHITE_LABEL</code>, <code>MULTI_STORE</code>, <code>MCP_ACCESS</code></td></tr><tr><td>Essai libre de 60 jours</td><td><code>PlatformTrial</code> (RG-PLAT-51 à 57)</td><td>Compteur à la première vente, plafonds, relances. À la fin : lecture seule 15 jours, puis suspension</td></tr><tr><td>Clés d&#39;API</td><td>Spec 01 § 6, <a href="/VendoraSystem-docs/architecture/api-publique">API publique</a></td><td>Nombre de clés et débit par minute par formule (<code>429 RATE_LIMITED</code>). <strong>Pas de compteur mensuel</strong></td></tr><tr><td>Assistant IA</td><td><code>MCP_ACCESS</code> (RG-PLAT-58), migration V99</td><td>Droit <strong>actif dans toutes les formules</strong> depuis le 11/11</td></tr><tr><td>Facturation</td><td>Console (RG-PLAT-25 à 29)</td><td>Manuelle, par virement, <strong>en euros seulement</strong>. Un prix en dinars s&#39;affiche mais n&#39;est pas facturable (RG-PLAT-46)</td></tr></tbody></table><h3 id="les-lots" tabindex="-1">Les lots <a class="header-anchor" href="#les-lots" aria-label="Permalink to &quot;Les lots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Lot</th><th>Contenu</th><th>Dépend de</th><th>Effort estimé</th></tr></thead><tbody><tr><td><strong>ME0 — Décisions préalables</strong> (sans code)</td><td><ul><li>Valider les prix et les quotas.</li><li>Trancher la <strong>facturation en dinars</strong> (carte « Prestations en Tunisie : dinars ou euros ? »), indispensable pour vendre en Tunisie.</li><li>Choisir ce que deviennent les appareils en trop quand un commerce redescend en Gratuit (voir plus bas).</li><li>Validation comptable des factures (RG-PLAT-26).</li></ul></td><td>—</td><td>Décisions d&#39;Ahmed</td></tr><tr><td><strong>ME1 — Catalogue et prix par pays</strong></td><td><ul><li>Les formules Gratuit, Commerce, Restaurant et Sur mesure deviennent une nouvelle version du catalogue. Essentiel est retiré pour les nouveaux clients, et les clients existants gardent leur prix figé.</li><li><strong>Prix par devise</strong> (EUR, TND) sur chaque formule et chaque option. Nouvelles limites <code>maxProducts</code> et <code>maxUsers</code>.</li><li>Catalogue public (<code>/public/plans</code>) et page Tarifs de la vitrine.</li><li>Facturation en dinars si ME0 l&#39;a décidé.</li></ul></td><td>ME0</td><td>≈ 1,5 semaine</td></tr><tr><td><strong>ME2 — Formule Gratuit</strong></td><td><ul><li>Limites appliquées par le serveur : 300 produits, 3 utilisateurs, 1 magasin, 1 appareil (<code>LIMIT_REACHED</code>, avec la formule qui lève la limite). Messages clairs dans le back-office et les deux apps.</li><li>Inscription possible directement en Gratuit.</li><li><strong>Fin d&#39;essai → descente en Gratuit</strong> au lieu de la lecture seule puis de la suspension (RG-PLAT-55 réécrite). La vente, les Z et la synchronisation ne sont jamais coupés (RG-PLAT-17).</li><li>Le Gratuit n&#39;est ni facturé ni compté dans le revenu récurrent. Nouvelle tuile « Gratuits » dans la console, avec le taux de passage en payant.</li></ul></td><td>ME1</td><td>≈ 2 semaines</td></tr><tr><td><strong>ME3 — Découpage des modules</strong></td><td><ul><li><code>CREDIT</code> devient l&#39;<strong>ardoise de base</strong> et passe dans toutes les formules.</li><li>Nouveaux modules : <code>CREDIT_ADVANCED</code> (rappels, rapport des ardoises ouvertes, points différés), <code>STOCK_ADVANCED</code> (inventaire, lots et dates limites, coût moyen), <code>REPORTS_ADVANCED</code> (rapports complets, email quotidien), <code>ACCOUNTING_EXPORT</code> (FEC, journaux).</li><li>Les modules sont masqués sur Android, iOS et le web, et refusés par le serveur.</li><li>Parité des deux apps, captures, pages du centre d&#39;aide.</li></ul></td><td>ME1</td><td>≈ 2,5 semaines</td></tr><tr><td><strong>ME4 — Mention « Propulsé par Vendora »</strong></td><td>Pied du ticket imprimé et du reçu digital pour la formule Gratuit, hors zone fiscale. Rendu ESC/POS 58 et 80 mm.</td><td>ME2</td><td>≈ 3 jours</td></tr><tr><td><strong>ME5 — API : quota mensuel et paiement à l&#39;usage</strong></td><td><ul><li>Compteur d&#39;appels mensuel par commerce, sans les clés « Assistant IA » ni les webhooks. En-têtes <code>X-Quota-Limit</code> / <code>X-Quota-Remaining</code>, alertes à 80 % et 100 %.</li><li><strong>France</strong> : ligne « appels au-delà du quota » sur la facture mensuelle, plafond de dépense réglable (50 € par défaut), refus <code>429 QUOTA_EXCEEDED</code> une fois le plafond atteint.</li><li><strong>Tunisie</strong> : packs prépayés de 10 000 appels vendus depuis la console, avec un solde décompté.</li><li>Page Clés d&#39;API (consommation du mois) et fiche client de la console.</li><li><a href="/VendoraSystem-docs/architecture/api-publique">API publique</a> et OpenAPI mis à jour dans le même lot.</li></ul></td><td>ME1 (+ ME0 pour les dinars)</td><td>≈ 2 semaines</td></tr><tr><td><strong>ME6 — Option Assistant IA</strong></td><td><ul><li><code>MCP_ACCESS</code> est retiré des formules, sauf Sur mesure, et devient une <strong>option</strong> de l&#39;abonnement.</li><li><strong>3 mois offerts</strong> à la souscription d&#39;une formule payante, avec email à J-7. À la fin de l&#39;offre, l&#39;option est facturée si le client l&#39;a gardée, sinon l&#39;accès des clés « Assistant IA » est coupé (rien n&#39;est supprimé).</li><li>Le Gratuit n&#39;y a pas accès.</li><li>Migration qui corrige V99.</li></ul></td><td>ME1, ME7</td><td>≈ 1 semaine</td></tr><tr><td><strong>ME7 — Options payantes dans l&#39;abonnement</strong></td><td><ul><li>Lignes de facture pour le kiosque par borne, l&#39;e-reporting en Commerce France et le support prioritaire. L&#39;appareil supplémentaire existe déjà, son prix passe par pays.</li><li>Ajout et retrait par l&#39;équipe dans la console, et affichage dans la page Abonnement du client.</li></ul></td><td>ME1</td><td>≈ 1,5 semaine</td></tr><tr><td><strong>ME8 — Vitrine, aide et specs</strong></td><td><ul><li>Page Tarifs avec le comparatif des formules, et une FAQ « Pourquoi gratuit ? ».</li><li>Centre d&#39;aide FR / EN / AR (formule Gratuit, limites, quota de l&#39;API, option IA).</li><li>Specs 01, 06, 12 et 17 à jour.</li><li>Site, TRACKING et captures à chaque lot.</li></ul></td><td>Au fil des lots</td><td>En continu</td></tr></tbody></table><p><strong>Ordre conseillé</strong> : ME0 → ME1 → ME2 et ME3, qui peuvent avancer en parallèle (fichiers différents) → ME7 → ME4, ME5 et ME6. Total d&#39;environ <strong>10 à 11 semaines</strong> de développement, hors décisions et terrain. <strong>[Estimation]</strong></p><h3 id="points-a-trancher-avant-ou-pendant-les-lots" tabindex="-1">Points à trancher avant ou pendant les lots <a class="header-anchor" href="#points-a-trancher-avant-ou-pendant-les-lots" aria-label="Permalink to &quot;Points à trancher avant ou pendant les lots&quot;">​</a></h3><ol><li><strong>Facturation en dinars</strong> : sans elle, ni les formules ni les packs d&#39;API ne sont facturables en Tunisie. C&#39;est bloquant pour ME1 côté Tunisie.</li><li><strong>Appareils en trop à la descente en Gratuit</strong> : un commerce qui avait 3 caisses pendant l&#39;essai n&#39;a plus droit qu&#39;à 1. Proposition : 15 jours de grâce, puis le propriétaire choisit la caisse qui continue de vendre. Les autres passent en lecture seule mais <strong>synchronisent</strong> leurs ventes déjà faites, sans jamais rien perdre (RG-PLAT-17).</li><li><strong>Produits au-delà de 300</strong> à la descente : ils restent vendables (rien n&#39;est désactivé, RG-PLAT-15), seule la création est bloquée.</li><li><strong>Clients déjà inscrits</strong> (staging, pilotes) : ils gardent leur formule et leur prix figé. La nouvelle grille ne s&#39;applique qu&#39;aux nouvelles souscriptions.</li></ol></div>',1)])])}const g=e(d,[["render",i]]);export{m as __pageData,g as default};
